import {THESIS,ZoneTracker,interactionRates,summarize,validateSale,validateSession} from './research.js';
import {loadDetector} from './detector.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(n),fmt=(n,d=1)=>n===null||n===undefined?'—':Number(n).toLocaleString('es-PE',{maximumFractionDigits:d});
export class ResearchUI{
 constructor({getProject,changed,notify,download,navigate}){
  Object.assign(this,{getProject,changed,notify,download,navigate,active:false,tracker:new ZoneTracker(),generation:0,pending:false,lastInfer:0,context:null,model:null,lastResult:null});
  this.snapshot=document.createElement('canvas');
  document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));
  $('vision-mode').onchange=()=>{this.resetVision();$('measure-stop').click();this.notify('Método cambiado. Inicia una nueva medición.');};
  $('event-list').onclick=e=>{const b=e.target.closest('[data-event]');if(!b||this.active)return;const ev=this.tracker.events.find(x=>x.id===b.dataset.event);if(ev){ev.status=b.dataset.verdict;this.renderEvents();}};
  $('missed-events').oninput=()=>this.renderEvents();
  $('save-session').onclick=()=>this.saveSession();
  $('interaction-mode').onchange=()=>{this.getProject().interactionMode=$('interaction-mode').value;this.changed();};
  $('sale-form').onsubmit=e=>{e.preventDefault();this.addSale();};
  $('sale-product').onchange=()=>this.priceDefaults();
  for(const [id,key] of [['hours-before','antes'],['hours-after','despues']])$(id).onchange=()=>{const n=Number($(id).value);if(!Number.isFinite(n)||n<0||n>1e6)return this.notify('Revisa las horas de operación.',true);const p=this.getProject();p.salesHours={...(p.salesHours||{}),[key]:n};this.changed();};
  for(const [id,key] of [['sales-table','sales'],['sessions-table','sessions']])$(id).onclick=e=>{const b=e.target.closest('[data-remove-record]');if(!b)return;const p=this.getProject();p[key]=p[key].filter(s=>s.id!==b.dataset.removeRecord);this.changed();};
  $('download-study').onclick=()=>this.exportReport();$('print-study').onclick=()=>{this.renderReport();window.print();};
  $('sale-date').value=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
  this.refresh();this.renderEvents();this.renderHeat();
 }
 refresh(){
  const p=this.getProject();p.sessions=p.sessions||[];p.sales=p.sales||[];
  for(const id of ['observation-product','sale-product']){const prev=$(id).value;$(id).innerHTML=p.productos.map(x=>`<option value="${esc(x.sku)}">${esc(x.name)} · ${esc(x.sku)}</option>`).join('');if(p.productos.some(x=>x.sku===prev))$(id).value=prev;}
  this.priceDefaults();$('interaction-mode').value=p.interactionMode||'proxy';$('hours-before').value=p.salesHours?.antes||0;$('hours-after').value=p.salesHours?.despues||0;
  let rates,totals;try{rates=interactionRates(p);totals=summarize(p);}catch(e){this.notify(e.message,true);return;}
  const eligible=p.productos.filter(x=>x.stock>0&&x.max_faces>0),n=eligible.filter(x=>rates.has(x.sku)).length,events=totals.antes.events+totals.despues.events;
  $('home-events').textContent=p.sessions.length?fmt(events,0):'—';$('home-event-note').textContent=p.sessions.length?`${p.sessions.length} sesiones revisadas · no personas únicas`:'Aún no hay sesiones guardadas';$('home-margin').textContent=p.sales.length?money(totals.antes.margin+totals.despues.margin):'—';$('home-calibrated').textContent=`${n} / ${eligible.length}`;
  $('calibration-status').textContent=`${n} de ${eligible.length} productos elegibles tienen sesiones revisadas. ${n===eligible.length?'Puedes usar el modo calibrado.':'El modo calibrado requiere datos para todos; el exploratorio usa el índice de actividad.'}`;
  $('readiness').textContent=n===eligible.length&&p.sales.length?'Evidencia disponible':'En preparación';$('evidence-heading').textContent=p.sessions.length?'Evidencia vinculada a tus productos':'Empieza con evidencia real';$('evidence-text').textContent=p.sessions.length?`${p.sessions.length} sesiones y ${p.sales.length} registros de venta. La calibración se calcula a partir de los eventos revisados, sin rellenar datos faltantes.`:'El catálogo inicial es ficticio. Las métricas comerciales se completan con tus observaciones y ventas.';
  const steps=[['01','Observa y delimita','Conecta cámaras o abre un video.','actividad',p.sessions.length>0],['02','Revisa la interacción','Confirma eventos y registra ventas reales.','evidencia',p.sessions.length>0&&p.sales.length>0],['03','Compara tus objetivos','Resuelve la distribución con restricciones.','optimizar',!!this.lastResult],['04','Contrasta los resultados','Compara antes y después; exporta evidencia.','informe',totals.antes.sessions>0&&totals.despues.sessions>0]];
  $('study-steps').innerHTML=steps.map(([i,title,desc,page,done])=>`<div class="study-step ${done?'done':''}"><span class="step-number">${done?'✓':i}</span><div><h3>${title}</h3><p>${desc}</p></div><button data-next="${page}" aria-label="${title}">↗</button></div>`).join('');$('study-steps').onclick=e=>{const b=e.target.closest('[data-next]');if(b)this.navigate(b.dataset.next);};
  this.renderRecords();this.renderReport();
 }
 priceDefaults(){const p=this.getProject().productos.find(x=>x.sku===$('sale-product').value);if(p){$('sale-price').value=p.price;$('sale-cost').value=p.cost;}}
 cameras(count,connected){$('home-cameras').textContent=count;$('home-camera-note').textContent=connected?'Pestaña de Hik-Connect compartida':'Conecta la vista de Hik-Connect';}
 async prepareVision(){
  const p=this.getProject(),product=p.productos.find(x=>x.sku===$('observation-product').value),s=p.anaqueles[Number($('target-shelf').value)],fronts=Number($('observation-fronts').value),dwell=Number($('dwell').value),confidence=Number($('confidence').value)/100;
  if(!product||!s||!Number.isInteger(fronts)||fronts<1||fronts>100||!Number.isFinite(dwell)||dwell<1||dwell>60||!Number.isFinite(confidence)||confidence<.2||confidence>.95||!Number.isFinite(s.visibility)||s.visibility<=0)throw Error('Revisa producto, anaquel, frentes, visibilidad y umbrales de detección.');
  $('detector-state').textContent='Cargando detector de personas en este equipo…';this.model=await loadDetector();$('detector-state').textContent='Detector listo · COCO-SSD · sin reconocimiento de identidad';
  return {sku:product.sku,producto:product.name,anaquel:s.name,visibility:s.visibility,fronts,phase:$('observation-phase').value,dwell,confidence};
 }
 beginVision(context,options){this.resetVision();this.tracker=new ZoneTracker({dwell:options.dwell,confidence:options.confidence});this.context={...context,...options};this.active=true;$('missed-events').value=0;$('session-notes').value='';this.renderEvents();}
 resetVision(){this.generation++;this.active=false;this.context=null;this.tracker.reset();this.lastInfer=0;$('save-session').disabled=true;$('people-now').textContent='0';$('candidate-count').textContent='0';this.renderEvents();this.renderHeat();}
 async onFrame(canvas,time,roi){
  if(!this.active||this.pending||performance.now()-this.lastInfer<450)return;
  this.lastInfer=performance.now();this.pending=true;const generation=this.generation;
  try{
   this.snapshot.width=canvas.width;this.snapshot.height=canvas.height;this.snapshot.getContext('2d').drawImage(canvas,0,0);
   const predictions=await this.model.detect(this.snapshot,30,this.tracker.confidence);
   if(!this.active||generation!==this.generation)return;
   const events=this.tracker.sample(predictions,time,canvas.width,canvas.height,roi);
   $('people-now').textContent=this.tracker.inside;$('candidate-count').textContent=this.tracker.events.length;
   $('detector-state').textContent=`Detector activo · ${fmt(this.tracker.seconds)} s con cobertura · ${this.tracker.boxes.length} detecciones en imagen`;
   if(events.length)this.renderEvents();this.renderHeat();
  }catch(e){if(generation===this.generation){this.active=false;$('measure-stop').click();this.notify(`No se completó la detección: ${e.message}`,true);}}finally{this.pending=false;}
 }
 paintHeat(ctx,w,h){const el=document.getElementById('heat-overlay');if(el&&!el.checked)return;const heat=this.tracker.heat,max=Math.max(...heat);if(!(max>0))return;const ramp=t=>{const k=[[0,[40,80,220]],[.35,[40,200,150]],[.6,[240,220,60]],[.85,[245,140,40]],[1,[230,40,40]]];for(let i=1;i<k.length;i++)if(t<=k[i][0]){const a=k[i-1],b=k[i],u=(t-a[0])/(b[0]-a[0]);return a[1].map((v,j)=>Math.round(v+(b[1][j]-v)*u));}return k[k.length-1][1];};ctx.save();ctx.globalCompositeOperation='source-over';const cw=w/12,ch=h/7;heat.forEach((n,i)=>{if(!n)return;const t=Math.sqrt(n/max),[r,g,b]=ramp(t),cx=(i%12+.5)*cw,cy=(Math.floor(i/12)+.5)*ch,rad=Math.max(cw,ch)*1.15,gr=ctx.createRadialGradient(cx,cy,0,cx,cy,rad);gr.addColorStop(0,`rgba(${r},${g},${b},${.15+.5*t})`);gr.addColorStop(1,`rgba(${r},${g},${b},0)`);ctx.fillStyle=gr;ctx.fillRect(cx-rad,cy-rad,rad*2,rad*2);});ctx.restore();}
 paint(ctx,w,h){this.paintHeat(ctx,w,h);if(!this.active)return;ctx.save();ctx.font='12px Segoe UI';for(const b of this.tracker.boxes){ctx.strokeStyle=b.inside?'#b9f28a':'#7ecad7';ctx.lineWidth=2;ctx.strokeRect(b.x*w,b.y*h,b.w*w,b.h*h);const label=`T${b.id} · ${Math.round(b.score*100)}%${b.inside?' · '+fmt(b.dwell)+' s':''}`;ctx.fillStyle='#0b283de8';ctx.fillRect(b.x*w,Math.max(0,b.y*h-20),Math.min(165,b.w*w+60),20);ctx.fillStyle='#e8f7ec';ctx.fillText(label,b.x*w+4,Math.max(14,b.y*h-6));}ctx.restore();}
 endVision(){this.active=false;this.generation++;this.renderEvents();if(this.context)$('detector-state').textContent=`Sesión detenida · ${fmt(this.tracker.seconds)} s con cobertura de detección. Revisa los eventos.`;}
 renderEvents(){
  const events=this.tracker.events,pending=events.filter(x=>x.status==='pending').length;
  $('review-count').textContent=`${events.length} candidatos · ${pending} pendientes`;
  $('event-list').innerHTML=events.length?events.map(e=>`<div class="event ${e.status}"><div><b>Evento ${esc(e.id)} · trayectoria T${e.track}</b><small>${fmt(e.time-(this.context?.startTime||0))} s de sesión · ${fmt(e.seconds)} s en zona · ${e.status==='approved'?'Confirmado':e.status==='rejected'?'Descartado':'Pendiente'}</small></div><button class="secondary" data-event="${esc(e.id)}" data-verdict="approved" ${this.active?'disabled':''}>Confirmar</button><button class="secondary" data-event="${esc(e.id)}" data-verdict="rejected" ${this.active?'disabled':''}>Descartar</button></div>`).join(''):`<p class="muted">${this.active?'Observando la zona. Los candidatos aparecerán al superar la permanencia mínima.':'No hay candidatos en esta sesión. Puedes guardar una observación de cero interacciones si tuvo cobertura suficiente.'}</p>`;
  const missed=Number($('missed-events').value);$('save-session').disabled=this.active||!this.context||this.tracker.seconds<10||pending>0||!Number.isInteger(missed)||missed<0;
 }
 renderHeat(){const max=Math.max(1,...this.tracker.heat);$('heatmap').innerHTML=this.tracker.heat.map((n,i)=>`<rect x="${(i%12)*30+1}" y="${Math.floor(i/12)*30+1}" width="27" height="27" rx="4" fill="${n?'#2c947f':'#e9f0ed'}" opacity="${n?.2+.8*n/max:1}"><title>${fmt(n)} segundos de detecciones</title></rect>`).join('');}
 saveSession(){try{if($('save-session').disabled)return;const c=this.context,s=validateSession({...c,id:crypto.randomUUID(),seconds:this.tracker.seconds,confirmed:this.tracker.events.filter(x=>x.status==='approved').length,rejected:this.tracker.events.filter(x=>x.status==='rejected').length,missed:Number($('missed-events').value),notes:$('session-notes').value,events:structuredClone(this.tracker.events),method:'COCO-SSD + permanencia en zona + revisión humana'});const p=this.getProject();p.sessions.push(s);this.context=null;this.changed();$('save-session').disabled=true;this.notify('Sesión revisada guardada y vinculada al producto.');}catch(e){this.notify(e.message,true);}}
 addSale(){try{const s=validateSale({id:crypto.randomUUID(),date:$('sale-date').value,phase:$('sale-phase').value,sku:$('sale-product').value,quantity:Number($('sale-quantity').value),price:Number($('sale-price').value),cost:Number($('sale-cost').value)});s.producto=this.getProject().productos.find(x=>x.sku===s.sku)?.name||s.sku;this.getProject().sales.push(s);this.changed();this.notify('Venta registrada con su precio y costo históricos.');}catch(e){this.notify(e.message,true);}}
 renderRecords(){const p=this.getProject();$('session-total').textContent=`${p.sessions.length} sesiones`;const table=(head,rows,empty)=>rows.length?`<table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table>`:`<div class="record-empty"><span>◎</span><h3>${empty}</h3><p>Los datos aparecerán cuando guardes tus registros.</p></div>`;
  $('sessions-table').innerHTML=table(['Producto','Anaquel','Etapa','Cobertura','Confirmadas + omitidas','Descartadas','Acción'],p.sessions.map(s=>`<tr><td>${esc(s.producto||s.sku)}</td><td>${esc(s.anaquel)}</td><td>${s.phase==='antes'?'Antes':'Después'}</td><td>${fmt(s.seconds)} s</td><td>${s.confirmed} + ${s.missed}</td><td>${s.rejected}</td><td><button class="remove" data-remove-record="${esc(s.id)}" aria-label="Eliminar sesión de ${esc(s.producto)}">×</button></td></tr>`),'Todavía no hay sesiones revisadas');
  $('sales-table').innerHTML=table(['Fecha','Producto','Etapa','Unidades','Ingreso','Costo variable','Margen','Acción'],p.sales.map(s=>`<tr><td>${esc(s.date)}</td><td>${esc(s.producto||s.sku)}</td><td>${s.phase==='antes'?'Antes':'Después'}</td><td>${s.quantity}</td><td>${money(s.quantity*s.price)}</td><td>${money(s.quantity*s.cost)}</td><td><b>${money(s.quantity*(s.price-s.cost))}</b></td><td><button class="remove" data-remove-record="${esc(s.id)}" aria-label="Eliminar venta de ${esc(s.producto)}">×</button></td></tr>`),'Registra la primera venta observada');
 }
 result(r,chosen){this.lastResult=r;$('interaction-result-label').textContent=r.interactionMode==='calibrated'?'INTERACCIONES ESTIMADAS / HORA':'ÍNDICE EXPLORATORIO';$('interaction-result-note').textContent=r.interactionMode==='calibrated'?'Calibrado con sesiones revisadas':'Proxy de actividad; no interacciones observadas';this.drawPareto(r,chosen);this.refresh();}
 invalidate(){this.lastResult=null;this.refresh();}
 drawPareto(r,chosen){const points=[r.elegido,...r.frontera],maxX=Math.max(1,...points.map(p=>p.actividad))*1.12,maxY=Math.max(1,...points.map(p=>p.margen)),minY=Math.min(0,...points.map(p=>p.margen)),range=Math.max(1,maxY-minY)*1.15,x=v=>70+v/maxX*590,y=v=>260-(v-minY)/range*220;const ticks=Array.from({length:5},(_,i)=>i/4);
  $('pareto-chart').innerHTML=`<rect width="700" height="320" rx="12" fill="#fafcf9"/>${ticks.map(t=>`<line x1="70" x2="660" y1="${y(minY+t*range)}" y2="${y(minY+t*range)}" stroke="#e1eae4"/><text x="59" y="${y(minY+t*range)+4}" text-anchor="end" fill="#7c9286" font-size="11">${fmt(minY+t*range,0)}</text>`).join('')}<line x1="70" y1="260" x2="660" y2="260" stroke="#a8beb1"/><text x="365" y="305" text-anchor="middle" fill="#6c8377" font-size="11">${esc(r.interactionUnit)}</text><text x="18" y="24" fill="#6c8377" font-size="11">Margen (S/)</text>${ticks.map(t=>`<text x="${x(t*maxX)}" y="282" text-anchor="middle" fill="#7c9286" font-size="11">${fmt(t*maxX)}</text>`).join('')}<polyline points="${[...r.frontera].sort((a,b)=>a.actividad-b.actividad).map(p=>`${x(p.actividad)},${y(p.margen)}`).join(' ')}" fill="none" stroke="#a8c9ba" stroke-width="2"/>${points.map((p,i)=>`<circle cx="${x(p.actividad)}" cy="${y(p.margen)}" r="${p===chosen?8:5}" fill="${p===chosen?'#0d7163':'#90b99d'}" stroke="white" stroke-width="2"><title>${esc(p.nombre)}: ${money(p.margen)} / ${fmt(p.actividad)}</title></circle>`).join('')}`;
 }
 reportData(){const p=this.getProject();return {titulo:THESIS,fecha:new Date().toISOString(),procedencia:p.procedencia,periodo:p.periodo,observado:summarize(p),sesiones:p.sessions,ventas:p.sales,calibracion:Object.fromEntries(interactionRates(p)),optimizacion:this.lastResult,datos:structuredClone(p),limitaciones:['La detección por zona genera candidatos, revisados por el observador; no identifica personas únicas ni compras.','Las tasas por producto extrapolan con raíz de frentes y visibilidad; requieren validación de campo.','El margen observado proviene de ventas registradas; el estimado usa la hipótesis de demanda del modelo.','La comparación descriptiva antes/después no prueba un efecto causal.']};}
 renderReport(){const p=this.getProject(),s=summarize(p);$('study-report').innerHTML=`<div class="report-title"><p class="eyebrow">ANAQUELLAB · INFORME DE INVESTIGACIÓN</p><h2>${THESIS}</h2><p>Origen: ${esc(p.procedencia||'No indicado')} · Periodo del modelo: ${esc(p.periodo||'No indicado')}</p></div><h3>1. Evidencia observada</h3><div class="report-grid">${Object.entries(s).map(([key,v])=>`<div class="report-card"><h3>${key==='antes'?'Antes de redistribuir':'Después de redistribuir'}</h3><dl><div><dt>Sesiones revisadas</dt><dd>${v.sessions}</dd></div><div><dt>Interacciones revisadas</dt><dd>${v.sessions?v.events:'—'}</dd></div><div><dt>Interacciones / hora de observación*</dt><dd>${fmt(v.interactionsPerHour)}</dd></div><div><dt>Margen de ventas registradas</dt><dd>${p.sales.some(x=>x.phase===key)?money(v.margin):'—'}</dd></div><div><dt>Margen / hora de operación</dt><dd>${v.marginPerHour===null?'—':money(v.marginPerHour)}</dd></div></dl></div>`).join('')}</div><p class="hint">*Tasa agregada sobre horas de observación por producto. No representa afluencia única ni tasa global de la tienda. Compara igual composición de productos, cámaras y horarios.</p><h3>2. Recomendación del modelo</h3>${this.lastResult?`<p>Modo: <b>${this.lastResult.interactionMode==='calibrated'?'Calibrado con interacciones revisadas':'Exploratorio con índice de actividad'}</b>. Margen estimado del balance elegido: <b>${money(this.lastResult.elegido.margen)}</b> por ${esc(p.periodo)}. Objetivo de interacción: ${fmt(this.lastResult.elegido.actividad)} (${esc(this.lastResult.interactionUnit)}). Peso de margen: ${Math.round(this.lastResult.peso*100)}%.</p><p>Se respetaron restricciones de frentes enteros, ancho, stock y capital. Se muestran ${this.lastResult.frontera.length} alternativas de una frontera muestreada.</p>`:'<p>No hay una optimización vigente. Calcula la distribución con los datos actuales.</p>'}<h3>3. Alcance y validación</h3><div class="report-warning">Este informe describe los registros disponibles. No demuestra un aumento real de ventas ni causalidad. La precisión del detector y las hipótesis del modelo requieren validación en la microempresa.</div><p>El detector genera candidatos por permanencia junto al anaquel. La confirmación y las omisiones provienen de la revisión humana. El objetivo calibrado extrapola la tasa por producto con raíz de frentes y visibilidad; el modo exploratorio usa un índice de movimiento. Los precios y costos de las ventas conservan sus valores históricos.</p><h3>4. Datos para reproducir el análisis</h3><p>El archivo JSON incluye catálogo, anaqueles, sesiones con umbrales y tiempos, eventos revisados, ventas, tasas calibradas y la última optimización. Las imágenes no se incluyen ni se almacenan en el servidor. Conserva también los videos y el protocolo de observación bajo tus propias condiciones de acceso.</p>`;}
 exportReport(){try{this.download('AnaquelLab-estudio.json',this.reportData());}catch(e){this.notify(e.message,true);}}
}
